INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('91a7877d-6d9b-4ed0-b336-c1269efffd68', '21feff02-016d-46e2-bb9d-c27495133b1b', '123. óra: Dobáljunk kockákat!', 'Kísérletezés dobókockával, gyakoriság, relatív gyakoriság és valószínűség.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "15bbdd55-f7b0-42e8-b067-645fdb6827ef", "text": "Egy szabályos 6 oldalú dobókockával mekkora az esélye a 6-os dobásnak?", "type": "multiple-choice", "options": [{"id": "63212233-93f6-493c-a92e-be1b68f3dc43", "text": "1 a 6-ból (1/6)", "isCorrect": true}, {"id": "b0bba47a-8d92-412e-a6ce-9aff7f249616", "text": "1 a 2-ből", "isCorrect": false}, {"id": "384d4094-cfe3-41f3-bb9a-f9e734393fbe", "text": "100%", "isCorrect": false}, {"id": "f3cb73e1-b50c-49f0-89d7-9fef84a87e89", "text": "0%", "isCorrect": false}], "timeLimit": 15}, {"id": "759cc92d-0047-4920-90c1-fe78e31546c2", "text": "Mennyi a páros szám (2, 4, 6) dobásának valószínűsége dobókockával?", "type": "multiple-choice", "options": [{"id": "34d1ea2a-bdf2-4a7f-a4d7-7000a2c74005", "text": "3 a 6-ból (3/6 = 1/2 azaz 50%)", "isCorrect": true}, {"id": "9666464d-205b-48da-b3ca-b6d7133bd52a", "text": "1/6", "isCorrect": false}, {"id": "89da597f-4199-4f81-9fbf-438731a783ec", "text": "2/6", "isCorrect": false}, {"id": "00d1582b-a0f0-457e-88f3-9fc7e2b8bdc2", "text": "100%", "isCorrect": false}], "timeLimit": 15}, {"id": "595c7fae-3e31-448d-8851-f98ab085443a", "text": "Sok dobási kísérlet végrehajtásakor a relatív gyakoriság megközelíti az elméleti valószínűséget.", "type": "true-false", "options": [{"id": "4dd32e71-a920-4e36-84b1-771c7e2298d0", "text": "Igaz", "isCorrect": true}, {"id": "0f160da2-30ab-4231-8750-5469850f4eb5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d1d37ac8-446a-491b-bbc7-7e3ef07d65a5", "text": "Milyen esemény egy kockával 7-est dobni?", "type": "multiple-choice", "options": [{"id": "0d78e8c1-49f6-43ad-9e85-dc86e0c760db", "text": "Lehetetlen esemény (0%)", "isCorrect": true}, {"id": "7c40996b-fee4-45c9-b221-83de11b5bbcf", "text": "Biztos esemény", "isCorrect": false}, {"id": "8f45f7ae-f7d7-4683-8cdb-40031dbc0303", "text": "Lehetséges", "isCorrect": false}, {"id": "3858753c-ef8c-4bfb-96ab-236ced4dc91d", "text": "Véletlen", "isCorrect": false}], "timeLimit": 15}, {"id": "c86db158-8015-424f-a9f4-0c3fd4221dc1", "text": "Milyen esemény egy kockával 1 és 6 közötti számot dobni?", "type": "multiple-choice", "options": [{"id": "39da0965-b9c9-45e5-96d2-f85679f779b7", "text": "Biztos esemény (100%)", "isCorrect": true}, {"id": "c8d3517c-2b13-4cd8-a613-312377e24175", "text": "Lehetetlen", "isCorrect": false}, {"id": "e1553474-3810-4815-b7a5-a15cdf1b3adc", "text": "Kétes", "isCorrect": false}, {"id": "4cbb4053-24ab-46a9-99da-3be8cce969bb", "text": "Ritka", "isCorrect": false}], "timeLimit": 15}, {"id": "6727850c-e255-48df-a9e3-4446e109e805", "text": "Hányféle kimenetele lehet két kocka dobásakor a kapott összegeknek? (2-től 12-ig: 11-féle)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "40c56352-fd6c-4b79-a90f-e303f062cb74", "text": "Két kockával a leggyakoribb dobási összeg a 7.", "type": "true-false", "options": [{"id": "7a24858b-8e08-487b-ba04-57a56d2c0614", "text": "Igaz", "isCorrect": true}, {"id": "2f292a0e-02ce-47ef-b417-d082082e6e35", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('8d356ee4-4e9d-44f9-9815-381371403c5b', '21feff02-016d-46e2-bb9d-c27495133b1b', '124. óra: Dobáljunk pénzérmét!', 'Kísérletezés érmével, fej vagy írás, tapasztalati valószínűség.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "141a6579-575b-4bf3-b5ba-3b61d3786508", "text": "Egy szabályos pénzérme feldobásakor mekkora a fej dobás valószínűsége?", "type": "multiple-choice", "options": [{"id": "e24c4893-9341-46f3-bf17-1a97a50e3073", "text": "1 a 2-ből (1/2 azaz 50%)", "isCorrect": true}, {"id": "dec94a40-5379-49e2-91d3-584485242dd8", "text": "1/4", "isCorrect": false}, {"id": "14429faf-25b4-4d41-a655-929587b65fc3", "text": "100%", "isCorrect": false}, {"id": "036580d7-6593-4585-a20c-5addc3fe765d", "text": "0%", "isCorrect": false}], "timeLimit": 15}, {"id": "0f018425-7591-493e-81aa-4f46b1a50ac7", "text": "Ha 100-szor dobunk fel egy érmét, a fej dobások száma kb. 50 körül várható.", "type": "true-false", "options": [{"id": "f9744e1a-c26a-44ef-b804-068322ce8d18", "text": "Igaz", "isCorrect": true}, {"id": "2aa88d60-0b19-4b7a-b2c3-254d2d644698", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "70cb2585-8336-4367-ac99-4d19914bc423", "text": "Hány kimenetele lehet 2 érme egyidejű feldobásának? (FF, FI, IF, II)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "e6505437-c4c1-49d3-9b9c-58c7df94be84", "text": "Mekkora a valószínűsége annak, hogy 2 érmével mindkettő fej lesz? (1 a 4-ből = 25%)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "b4f71022-65d8-46c8-b574-2b0e36c99619", "text": "A véletlen kísérletek eredményét az egyes próbálkozásoknál nem lehet pontosan kiszámítani, de nagy számnál szabályszerűség mutatkozik.", "type": "true-false", "options": [{"id": "f32c0188-3514-4f73-91ef-990a1ad7bafc", "text": "Igaz", "isCorrect": true}, {"id": "b9b36454-b1ac-4c67-aef8-e6902e21875e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "026a297f-0a7a-4207-b33a-0e28f3d52ce6", "text": "A biztos esemény valószínűsége 100% (vagy 1).", "type": "true-false", "options": [{"id": "971a6bc2-87f1-4e78-9a13-34f1dda16712", "text": "Igaz", "isCorrect": true}, {"id": "7aab9836-2c58-497e-b170-2bdaab196e60", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c97fea4c-176f-49ac-826a-8daf381e8e2c", "text": "A lehetetlen esemény valószínűsége 0% (vagy 0).", "type": "true-false", "options": [{"id": "505c4659-5594-4f63-a563-7f44a4f737c7", "text": "Igaz", "isCorrect": true}, {"id": "e6a34d7c-2b26-4ad6-8585-0ab8a529fa29", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('f723df99-21df-4ea5-b730-1838de170804', '21feff02-016d-46e2-bb9d-c27495133b1b', '125. óra: Összefoglalás', 'Statisztikai és valószínűségi ismeretek összefoglalása.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "bb58e9bc-ac61-4fca-99fc-e565cc857fcb", "text": "Mennyi a 6, 8, 10, 12 számok átlaga? (36 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "fb9a8cf4-a94e-41f8-8733-5722e671118b", "text": "Hány fokos körcikk felel meg a kördiagramon a 50%-nak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "6daf5634-36dc-47c7-a71b-c7c66b8477e6", "text": "Hány fokos körcikk felel meg a kördiagramon a 25%-nak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "0a85edd2-ce00-425b-b13a-8fe59d854abf", "text": "Egy kockával 6-ost dobni 1/6 valószínűségű esemény.", "type": "true-false", "options": [{"id": "e762897a-37e7-4491-a0ad-d519484234c5", "text": "Igaz", "isCorrect": true}, {"id": "d44e1581-d467-4a21-8e82-5ef227c8da51", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dfa9339a-14a1-4931-b9aa-05973744d995", "text": "Az adatok átlagához az összes adat összegét elosztjuk a darabszámmal.", "type": "true-false", "options": [{"id": "75202eb3-6a1b-409e-a6d5-f63c3aa29dfe", "text": "Igaz", "isCorrect": true}, {"id": "b36b4cb2-1948-4286-8b6d-b88535fc8c05", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e38a3dd4-a316-4fb6-86d3-4d9eaf098019", "text": "Melyik grafikon alkalmas időbeli változás ábrázolására?", "type": "multiple-choice", "options": [{"id": "06eddbbb-4e71-4590-bdbf-7cc57377e6d1", "text": "Vonaldiagram", "isCorrect": true}, {"id": "e2ef5136-f53b-4f5b-a8d4-dc174d2ccdfa", "text": "Kördiagram", "isCorrect": false}, {"id": "497d89e0-6585-4d5b-a5c9-c894fed86c80", "text": "Pontdiagram", "isCorrect": false}, {"id": "cbb1e156-5806-4abb-ba14-9e5b2f388aa9", "text": "Képrejtvény", "isCorrect": false}], "timeLimit": 15}, {"id": "52690ecf-2c4c-4631-99e9-debba0597e9f", "text": "Mennyi a 20 és 40 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW()),
('7252676c-f205-4503-9276-48a0a9241413', '21feff02-016d-46e2-bb9d-c27495133b1b', '126. óra: Számonkérés', 'Számonkérés projektmunka és teszt formájában a Statisztikából (10 kérdés).', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "9a93d390-baeb-4478-9e76-33059794d911", "text": "1. Mennyi a 10, 20, 30 számok átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "1e157f70-92cc-4854-b4b2-9b22b26872a2", "text": "2. Mennyi a 2, 4, 6, 8, 10 számok átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "6bccf7b7-6ed6-4e26-a873-3aea7e6893ee", "text": "3. Hány fokos a teljes kör a kördiagramon?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "c29d1acb-659f-4853-b83f-62bad52e44fa", "text": "4. Hány fokos körcikk jelöli a 10%-ot a kördiagramon?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "4e7e6fa5-0408-425e-96e9-76c426001d4e", "text": "5. Mekkora a fej dobás valószínűsége százalékban egy szabályos érmével?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "82b757fa-0d8d-4407-967d-888db34b277c", "text": "6. Milyen esemény egy 6 oldalú kockával 8-ast dobni?", "type": "multiple-choice", "options": [{"id": "2b5eea22-20bc-455a-8f09-4bc1f3285ffd", "text": "Lehetetlen esemény", "isCorrect": true}, {"id": "32db7188-a521-4c9e-8fe7-d6c4199fe14a", "text": "Biztos esemény", "isCorrect": false}, {"id": "7f70e09e-6808-49ac-a09d-51db6bb88538", "text": "Lehetséges", "isCorrect": false}, {"id": "b7966379-3c73-4db5-9994-6c731d8390aa", "text": "Döntetlen", "isCorrect": false}], "timeLimit": 15}, {"id": "31230797-f9e9-4f0d-9fac-c9e6596b44a3", "text": "7. Milyen esemény egy 6 oldalú kockával 1 és 6 közötti számot dobni?", "type": "multiple-choice", "options": [{"id": "dd3cccbe-2f95-496f-b2d9-bc01b1672762", "text": "Biztos esemény", "isCorrect": true}, {"id": "f0574de1-62f0-4de4-ac22-b719bcb5bbec", "text": "Lehetetlen esemény", "isCorrect": false}, {"id": "52e3fdd2-d4d6-492b-8148-0da7050cd355", "text": "Ritka", "isCorrect": false}, {"id": "9eff26a2-1abd-4fe7-b1fd-2a8bb4ab882b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9b93f0a9-a758-482f-82cb-54de5a92f3c4", "text": "8. Az adatok átlaga mindig a legkisebb és legnagyobb adat közé esik.", "type": "true-false", "options": [{"id": "9b77d42e-e86a-4722-83ea-4843c8bfc58f", "text": "Igaz", "isCorrect": true}, {"id": "5a35f510-b391-440e-a80c-4dde93a4cce1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b8da0f83-877f-447c-b40a-c976081019b9", "text": "9. Hány kimenetele lehet 2 érme feldobásának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "b164ed3a-bb71-4d4d-b856-48dd984969db", "text": "10. A vonaldiagram az adatok időbeli alakulását mutatja meg jól.", "type": "true-false", "options": [{"id": "3eab9cae-55bd-4d4b-ac7f-d1a2ed258dcf", "text": "Igaz", "isCorrect": true}, {"id": "19a1ece8-8ad5-40dd-b427-d1b166486006", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('b2bf19c9-01e4-4377-9d23-6ce2b0cdbe0c', '21feff02-016d-46e2-bb9d-c27495133b1b', '127. óra: A számonkérés értékelése', 'A statisztikai feladatok és projektmunkák megbeszélése, értékelése.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "0d22ec2d-96fb-4fc8-a4c2-7ea2800430de", "text": "Mi volt a projektmunka és a számonkérés legfőbb tanulsága?", "type": "multiple-choice", "options": [{"id": "0543b232-9802-41d8-b699-045ded0afd5e", "text": "Az adatok pontos rögzítése és a helyes skálázás elengedhetetlen a helyes diagramokhoz", "isCorrect": true}, {"id": "dc02aec2-2bd2-467c-a83b-0677a33371ac", "text": "A rajzolás nem fontos", "isCorrect": false}, {"id": "7c9e74bc-75c0-4140-b939-1c4db3946822", "text": "A számolást el kell hagyni", "isCorrect": false}, {"id": "e023338a-7dee-41cd-ada2-8e637afcdc1a", "text": "Mindegy a skála", "isCorrect": false}], "timeLimit": 15}, {"id": "23d0a4c1-717e-4385-922d-ec378c3da468", "text": "Az átlag kiszámításánál a darabszámmal való osztást nem szabad elfelejteni.", "type": "true-false", "options": [{"id": "95303e3d-7439-459c-a22a-d3f107bb5ebc", "text": "Igaz", "isCorrect": true}, {"id": "bc55e2d8-f325-4269-9e39-319b8cd49cb7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "33c48eab-2444-4878-9138-37e7d3643082", "text": "Mennyi a 12 és 18 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "09f2e426-98df-40c5-8c0d-d303586cadb0", "text": "A kördiagram körcikkei összefüggenek a százalékos megoszlással.", "type": "true-false", "options": [{"id": "6fba4b3d-bd7b-4740-a1ed-066ce379ed40", "text": "Igaz", "isCorrect": true}, {"id": "9f29ba4e-3dce-44a5-9c66-c4e79f22e651", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "099b738d-bf6c-446e-9335-f4b2c21acbcb", "text": "A kísérletek során nyert adatok segítenek megérteni a valószínűségi elveket.", "type": "true-false", "options": [{"id": "b5fa7b6f-3f44-485b-81cc-6514eedb2383", "text": "Igaz", "isCorrect": true}, {"id": "7f8e7739-931c-427c-a2ed-71fa19a17533", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bfa9ad01-4169-420e-931d-9594bfef15b9", "text": "Mennyi a 5, 10, 15 átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "8bd9ffbf-4e90-40a7-83cf-02505a69010a", "text": "A csoporteredmények bemutatása fejlesztette a kommunikációs készséget.", "type": "true-false", "options": [{"id": "fda1ecfd-22d0-49f1-ae6c-a47c43615f42", "text": "Igaz", "isCorrect": true}, {"id": "71983b56-74f1-4600-a064-05fa6197c2e3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());